#!/usr/bin/env node

const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const OUT_PATH = path.join(ROOT, 'public', 'js', 'app.bundle.js');
const SCRIPT_PATHS = [
  '/js/data/place-details.js',
  '/js/data/quiz-catalog.js',
  '/js/core/format.js',
  '/js/core/firebase.js',
  '/js/features/admin-render.js',
  '/js/features/admin-form.js',
  '/js/features/admin-data.js',
  '/js/features/admin-state.js',
  '/js/infrastructure/admin-repository.js',
  '/js/application/admin-usecases.js',
  '/js/features/admin-controller.js',
  '/js/domain/account-domain.js',
  '/js/features/account-form.js',
  '/js/features/account-data.js',
  '/js/features/account-state.js',
  '/js/infrastructure/account-repository.js',
  '/js/application/account-usecases.js',
  '/js/features/account-controller.js',
  '/js/features/app-view.js',
  '/js/features/app-events.js',
  '/js/app/bootstrap.js',
  '/js/features/home-state.js',
  '/js/features/home-data.js',
  '/js/data/level-medal-assets.js',
  '/js/infrastructure/home-repository.js',
  '/js/application/home-usecases.js',
  '/js/application/profile-usecases.js',
  '/js/infrastructure/profile-repository.js',
  '/js/features/home-render.js',
  '/js/features/home-controller.js',
  '/js/domain/event-domain.js',
  '/js/application/event-usecases.js',
  '/js/features/event-state.js',
  '/js/features/event-data.js',
  '/js/infrastructure/event-repository.js',
  '/js/features/event-render.js',
  '/js/features/event-controller.js',
  '/js/domain/classroom-domain.js',
  '/js/application/classroom-usecases.js',
  '/js/features/classroom-state.js',
  '/js/features/classroom-data.js',
  '/js/infrastructure/classroom-repository.js',
  '/js/features/classroom-form.js',
  '/js/features/classroom-render.js',
  '/js/features/classroom-controller.js',
  '/js/domain/shop-domain.js',
  '/js/application/shop-usecases.js',
  '/js/features/shop-state.js',
  '/js/features/shop-data.js',
  '/js/infrastructure/shop-repository.js',
  '/js/features/shop-render.js',
  '/js/features/shop-controller.js',
  '/js/domain/ranking-domain.js',
  '/js/features/ranking-render.js',
  '/js/features/ranking-data.js',
  '/js/features/ranking-state.js',
  '/js/infrastructure/ranking-repository.js',
  '/js/application/ranking-usecases.js',
  '/js/features/school-controller.js',
  '/js/features/quiz-session-state.js',
  '/js/features/quiz-controller.js',
  '/js/domain/quiz-domain.js',
  '/js/infrastructure/quiz-repository.js',
  '/js/features/quiz-render.js',
  '/js/features/quiz-popular-session.js',
  '/js/features/quiz-play.js',
  '/js/features/quiz-flow.js',
  '/js/application/quiz-usecases.js'
];

function buildBundle(scriptPaths) {
  const banner = [
    '/*',
    ' * Generated by scripts/build-app-bundle.js.',
    ' * Source files are loaded in public/index.html order.',
    ' */',
    ''
  ].join('\n');

  const chunks = scriptPaths.map(scriptPath => {
    const filePath = path.join(ROOT, 'public', scriptPath.replace(/^\//, ''));
    const source = fs.readFileSync(filePath, 'utf8').replace(/\s+$/, '');
    return [
      `/* ${scriptPath} */`,
      source,
      `//# sourceURL=${scriptPath}`,
      ''
    ].join('\n');
  });

  return `${banner}${chunks.join('\n')}`;
}

function main() {
  fs.writeFileSync(OUT_PATH, buildBundle(SCRIPT_PATHS));
  console.log(`Built ${path.relative(ROOT, OUT_PATH)} from ${SCRIPT_PATHS.length} files.`);
}

main();
